// Package paths centralizes every filesystem location the binary touches.
package paths

const (
	// ServiceName is the systemd unit name.
	ServiceName = "pve-real-memory"

	// BinaryDefault is where --install copies nothing; the operator uploads
	// the binary here and points the unit at it.
	BinaryDefault = "/usr/local/bin/pve-real-memory"

	// ConfigDir holds config.yaml and the SSH monitoring key.
	ConfigDir = "/etc/pve-real-memory"

	// ConfigFile is the YAML configuration.
	ConfigFile = ConfigDir + "/config.yaml"

	// SSHKeyDefault is the ed25519 private key generated by --install.
	SSHKeyDefault = ConfigDir + "/id_ed25519"

	// StateDir holds mutable runtime state: known_hosts, patch backups,
	// data migrated away from the legacy proxmox-rmem install.
	StateDir = "/var/lib/pve-real-memory"

	// KnownHosts is the SSH host key database.
	KnownHosts = StateDir + "/known_hosts"

	// PatchBackupDir holds timestamped copies of QemuServer.pm taken before
	// every successful patch application.
	PatchBackupDir = StateDir + "/patch-backups"

	// LegacyBackupDir holds everything removed by the legacy migration.
	LegacyBackupDir = StateDir + "/legacy-backup"

	// OverrideDir holds the per-VM memory override files read by the Perl
	// patch. It is a root-only tmpfs dir (systemd RuntimeDirectory), which
	// makes it immune to /tmp symlink attacks.
	OverrideDir = "/run/pve-real-memory"

	// UnitFile is the systemd service unit written by --install.
	UnitFile = "/etc/systemd/system/" + ServiceName + ".service"

	// AptHookFile is the DPkg::Post-Invoke snippet re-applying the patch
	// after Proxmox package upgrades.
	AptHookFile = "/etc/apt/apt.conf.d/99-" + ServiceName

	// LockFile serializes patch/uninstall/install/repair operations.
	LockFile = "/run/lock/" + ServiceName + ".lock"

	// QemuServerPM is the Proxmox module patched to read override files.
	QemuServerPM = "/usr/share/perl5/PVE/QemuServer.pm"

	// QGAServiceDir holds qemu-ga unix sockets (<vmid>.qga).
	QGAServiceDir = "/run/qemu-server"

	// ---- legacy proxmox-rmem locations, removed by the migration ----

	LegacyUnitFile      = "/etc/systemd/system/proxmox-rmem.service"
	LegacyAptHookFile   = "/etc/apt/apt.conf.d/99-proxmox-rmem"
	LegacyAptHelper     = "/usr/local/bin/proxmox-rmem-apt-hook.sh"
	LegacyScript        = "/usr/local/bin/proxmox-rmem.py"
	LegacyPatchScript   = "/usr/local/bin/proxmox-rmem-patch.py"
	LegacyConfigDir     = "/etc/proxmox-rmem"
	LegacyBackupPM      = QemuServerPM + ".bak"
	LegacyOverrideGlob  = "/tmp/pve-vm-*-mem-override"
	LegacyAutopatchLog  = "/var/log/proxmox-rmem-autopatch.log"
)
